import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const tokens = input.join(" ").split(/\s+/).map(Number);
const [x, y, e] = tokens;
const adj: number[][] = Array.from({ length: x + 1 }, () => []);
for (let i = 0; i < e; i++) adj[tokens[3 + 2 * i]].push(tokens[4 + 2 * i]);

// owner[b] = 研究室 b に割り当てられている学生（0 なら空き）
const owner = new Int32Array(y + 1);

// 学生 a を割り当てられるか試す。埋まっていれば、今の持ち主を別の研究室へ移せるか再帰的に試す
function assign(a: number, seen: Uint8Array): boolean {
  for (const b of adj[a]) {
    if (seen[b]) continue;
    seen[b] = 1;
    if (owner[b] === 0 || assign(owner[b], seen)) {
      owner[b] = a;
      return true;
    }
  }
  return false;
}

let matched = 0;
for (let a = 1; a <= x; a++) {
  if (assign(a, new Uint8Array(y + 1))) matched++;
}
console.log(matched);
